class TestFormalVerification(unittest.TestCase):
    def test_formal_proof_division_safe(self):
        code = """
@requires("b != 0")
@ensures("result * b == a or True")
def safe_div(a: int, b: int) -> int:
    return a // b
"""
        tree = ast.parse(code)
        func_node = tree.body[0]
        engine = Z3VerificationEngine(timeout_ms=40)
        result = engine.verify_function_ast(func_node, source_code=code)
        self.assertEqual(result.status, ProofStatus.PROVEN_SAFE)
        self.assertLess(result.solver_duration_ms, 50.0)
        self.assertIsNone(result.defect_type)

    def test_formal_defect_detection_division_by_zero(self):
        code = """
def unsafe_div(a: int, b: int) -> int:
    return a // b
"""
        tree = ast.parse(code)
        func_node = tree.body[0]
        engine = Z3VerificationEngine(timeout_ms=40)
        result = engine.verify_function_ast(func_node, source_code=code)
        self.assertEqual(result.status, ProofStatus.DEFECT_FOUND)
        self.assertEqual(result.defect_type, SafetyDefectType.ZERO_DIVISION)
        self.assertIsNotNone(result.counterexample)
        self.assertEqual(result.counterexample.get("b"), 0)
        self.assertTrue(result.witness_verified_at_runtime)
        self.assertLess(result.solver_duration_ms, 50.0)

