    def _verify_src(self, code: str):
        tree = ast.parse(code)
        func_node = next(n for n in tree.body if isinstance(n, ast.FunctionDef))
        return Z3VerificationEngine(timeout_ms=100).verify_function_ast(func_node, source_code=code)

