    def test_high_availability_failover_prover_detects_split_brain_and_lag_violations(self):
        from aleph_core.verification import HighAvailabilityFailoverProver, ClusterNodeSpec
        # Clúster de 2 nodos sin árbitro (riesgo de Split-Brain)
        two_node_cluster = [
            ClusterNodeSpec("db-node-1", "PRIMARY", current_term=1),
            ClusterNodeSpec("db-node-2", "REPLICA", current_term=1, replication_lag_bytes=2097152)  # Lag alto
        ]
        rep_two = HighAvailabilityFailoverProver.verify_failover_spec("ProdTwoNode", two_node_cluster, max_allowed_lag_bytes=1048576)
        self.assertFalse(rep_two.formal_safety_proven)
        self.assertFalse(rep_two.split_brain_safe)
        self.assertFalse(rep_two.data_loss_safe)

        # Clúster de 3 nodos con quórum estricto y réplica fresca
        three_node_cluster = [
            ClusterNodeSpec("db-node-1", "PRIMARY", current_term=2, is_fenced=True),
            ClusterNodeSpec("db-node-2", "REPLICA", current_term=2, replication_lag_bytes=1024),
            ClusterNodeSpec("db-node-3", "REPLICA", current_term=2, replication_lag_bytes=4096)
        ]
        rep_three = HighAvailabilityFailoverProver.verify_failover_spec("ProdHAQuorum", three_node_cluster, max_allowed_lag_bytes=1048576)
        self.assertTrue(rep_three.formal_safety_proven)
        self.assertTrue(rep_three.split_brain_safe)
        self.assertEqual(rep_three.promoted_node_id, "db-node-2")

