    def test_redteam_offensive_taint_crypto_and_antissrf_prover_node04(self):
        from aleph_core.verification import RedTeamOffensiveTaintCryptoAndAntiSSRFProver

        # 1. Verificar canonización algebraica multi-base y CVE-2026-31943 (IPv4-mapped IPv6)
        c_ipv6 = RedTeamOffensiveTaintCryptoAndAntiSSRFProver.canonicalize_ip_candidate("http://[::ffff:169.254.169.254]/latest/meta-data/")
        self.assertIsNotNone(c_ipv6)
        self.assertEqual(c_ipv6[0], "169.254.169.254")
        self.assertTrue(c_ipv6[1])

        c_octal = RedTeamOffensiveTaintCryptoAndAntiSSRFProver.canonicalize_ip_candidate("http://0251.0376.0251.0376/latest/")
        self.assertIsNotNone(c_octal)
        self.assertEqual(c_octal[0], "169.254.169.254")
        self.assertTrue(c_octal[1])

        c_dword = RedTeamOffensiveTaintCryptoAndAntiSSRFProver.canonicalize_ip_candidate("http://2852039166/meta")
        self.assertIsNotNone(c_dword)
        self.assertEqual(c_dword[0], "169.254.169.254")
        self.assertTrue(c_dword[1])

