    def test_craig_interpolation_and_cegar_prover(self):
        from aleph_core.verification import CraigInterpolationAndCEGARProver
        # Caso 1: UNSAT (A: x == y + 5 and y >= 0, B: x < 0) -> interpolante sobre x: x >= 0
        rep_safe = CraigInterpolationAndCEGARProver.synthesize_interpolant_and_refine(
            prefix_formula_a="x == y + 5 and y >= 0",
            error_formula_b="x < 0",
            initial_predicates=["y >= 0"]
        )
        self.assertTrue(rep_safe.property_proven_safe)
        self.assertIn("x", rep_safe.shared_interface_vocabulary)
        self.assertNotIn("y", rep_safe.shared_interface_vocabulary)
        self.assertIn("x >= 0", rep_safe.craig_interpolant)
        self.assertGreaterEqual(rep_safe.spurious_counterexamples_eliminated, 1)

        # Caso 2: SAT (A: x == y - 5 and y == 0, B: x < 0) -> existe contraejemplo concreto
        rep_unsafe = CraigInterpolationAndCEGARProver.synthesize_interpolant_and_refine(
            prefix_formula_a="x == y - 5 and y == 0",
            error_formula_b="x < 0"
        )
        self.assertFalse(rep_unsafe.property_proven_safe)
        self.assertEqual(rep_unsafe.concrete_counterexample_witness.get("x"), -5)


