        self.assertTrue(rep_good.causal_cut_consistent_verified)
        self.assertEqual(rep_good.converged_merged_state, {"node_a": 15, "node_b": 12})
        self.assertEqual(len(rep_good.pcc_certificate_sha256), 64)



