    def test_lehman_yao_blink_tree_and_optimistic_lock_coupling_prover(self):
        from aleph_core.verification import LehmanYaoBLinkTreeAndOptimisticLockCouplingProver
        # Case A: Sound Lehman-Yao B-Link split (right_link published with Release before parent insert), OLC hand-over-hand validation, and left-to-right latches
