    def test_phi_accrual_failure_detector_and_swim_lifeguard_gossip_prover(self):
        from aleph_core.verification import PhiAccrualFailureDetectorAndSWIMLifeguardGossipProver
        # Case A: Sound Phi-Accrual window (healthy peer not suspected, silent peer with Phi > 8.0 suspected), SWIM k=3 indirect probes + LHM scaling, and inc+1 refutation
