    def test_aead_key_commitment_nonce_reuse_cswsh_and_graphql_complexity_prover(self):
        from aleph_core.verification import AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver
        import hashlib, hmac

        # 1. AEAD Nonce-Reuse, NIST SP 800-38D Rotation & Key Commitment
        key = b"0123456789abcdef0123456789abcdef"
        nonce_ok = b"unique_nonce"
        commit_tag = hmac.new(key, b"ALEPH_KEY_COMMIT" + nonce_ok, hashlib.sha256).hexdigest()

        ok_aead, _ = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_aead_nonce_and_key_commitment(
            "AES-256-GCM", nonce_ok, 1024, commit_tag, commit_tag, set()
        )
        self.assertTrue(ok_aead)

        ok_zero, msg_zero = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_aead_nonce_and_key_commitment(
            "AES-256-GCM", b"\x00" * 12, 1, commit_tag, commit_tag, set()
        )
        self.assertFalse(ok_zero)
        self.assertIn("CWE-323", msg_zero)

        ok_rot, msg_rot = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_aead_nonce_and_key_commitment(
            "AES-256-GCM", nonce_ok, 4_294_967_296, commit_tag, commit_tag, set()
        )
        self.assertFalse(ok_rot)
        self.assertIn("NIST SP 800-38D", msg_rot)

        # 2. WebSocket CSWSH Origin & Constant-Time Token Verification
        ok_ws, _ = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_websocket_handshake_security(
            "https://studio.aleph.local", {"https://studio.aleph.local"}, "secret_ws_handshake_token_123", "secret_ws_handshake_token_123"
        )
        self.assertTrue(ok_ws)

        ok_cswsh, msg_cswsh = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_websocket_handshake_security(
            "https://evil.attacker.com", {"https://studio.aleph.local"}, "secret_ws_handshake_token_123", "secret_ws_handshake_token_123"
        )
        self.assertFalse(ok_cswsh)
        self.assertIn("CWE-1385", msg_cswsh)

        # 3. GraphQL Depth, Alias Amplification & Introspection Confinement
        ok_gql, _ = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_graphql_query_complexity(
            "query { user(id: 1) { id profile { displayName } } }", max_depth=5, max_aliases=5, allow_introspection=False
        )
        self.assertTrue(ok_gql)

        ok_intro, _ = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_graphql_query_complexity(
            "query { __schema { types { name } } }", max_depth=5, max_aliases=5, allow_introspection=False
        )
        self.assertFalse(ok_intro)

        ok_alias, _ = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.verify_graphql_query_complexity(
            "query { a1: login a2: login a3: login a4: login }", max_depth=5, max_aliases=2, allow_introspection=False
        )
        self.assertFalse(ok_alias)

        # 4. AST Security Audit
        vuln_src = (
            "async def bad_endpoint(websocket, aesgcm, schema, query):\n"
            "    await websocket.accept()\n"
            "    ct = aesgcm.encrypt(b'\\x00'*12, b'secret', None)\n"
            "    return schema.execute(query, introspection=True)\n"
        )
        rep_bad = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.audit_aead_cswsh_graphql_security(vuln_src)
        self.assertFalse(rep_bad.formal_aead_cswsh_graphql_safe)
        self.assertFalse(rep_bad.aead_nonce_and_commitment_clean)
        self.assertFalse(rep_bad.websocket_cswsh_origin_clean)
        self.assertFalse(rep_bad.graphql_depth_and_alias_clean)
        self.assertGreaterEqual(len(rep_bad.violations), 3)

        clean_src = "def safe_fn(a: int) -> int:\n    return a * 2\n"
        rep_clean = AEADKeyCommitmentNonceReuseCSWSHAndGraphQLComplexityProver.audit_aead_cswsh_graphql_security(clean_src)
        self.assertTrue(rep_clean.formal_aead_cswsh_graphql_safe)


    def test_ecdsa_rfc6979_invalid_curve_ssti_sandbox_and_ipv6_mapped_ssrf_prover(self):
        from aleph_core.verification import ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver

        # 1. ECDSA RFC 6979 + Low-S & ECDH Weierstrass On-Curve Point Validation
        # Curve y^2 = x^3 + 7 (mod 17), point (15, 13): 13^2 = 169 = 16 (mod 17); 15^3 + 7 = 3382 = 16 (mod 17)
        ok_ecc, _ = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_ecdsa_rfc6979_and_ecdh_point(
            r=5, s=4, curve_order_n=19, k_is_deterministic_rfc6979=True,
            px=15, py=13, prime_p=17, curve_a=0, curve_b=7, hkdf_derived=True
        )
        self.assertTrue(ok_ecc)

        ok_invalid_curve, msg_curve = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_ecdsa_rfc6979_and_ecdh_point(
            r=5, s=4, curve_order_n=19, k_is_deterministic_rfc6979=True,
            px=15, py=12, prime_p=17, curve_a=0, curve_b=7, hkdf_derived=True
        )
        self.assertFalse(ok_invalid_curve)
        self.assertIn("CWE-325", msg_curve)

        # 2. SSTI Jinja2 Confinement
        ok_ssti, _ = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_template_ssti_confinement(
            "Hola {{ user_name }}", uses_sandboxed_env=True, autoescape_enabled=True
        )
        self.assertTrue(ok_ssti)

        ok_mro, msg_mro = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_template_ssti_confinement(
            "{{ ''.__class__.__mro__[1].__subclasses__() }}", uses_sandboxed_env=True, autoescape_enabled=True
        )
        self.assertFalse(ok_mro)
        self.assertIn("CWE-1336", msg_mro)

        # 3. IPv6-Mapped IPv4 & Octal/Hex/Dword SSRF Prevention
        ok_ipv6_map, msg_map = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_canonical_ssrf_host(
            "[::ffff:169.254.169.254]", allow_redirects=False
        )
        self.assertFalse(ok_ipv6_map)
        self.assertIn("CWE-918", msg_map)

        ok_octal, msg_octal = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_canonical_ssrf_host(
            "0177.0.0.1", allow_redirects=False
        )
        self.assertFalse(ok_octal)
        self.assertIn("Octal", msg_octal)

        ok_pub, _ = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.verify_canonical_ssrf_host(
            "93.184.216.34", allow_redirects=False
        )
        self.assertTrue(ok_pub)

        # 4. AST Security Audit
        vuln_src = (
            "import jinja2, requests, random\n"
            "def bad_handler(user_tpl, target_url, sk):\n"
            "    k = random.randint(1, 1000)\n"
            "    sig = sk.ecdsa_sign(b'msg', k)\n"
            "    out = jinja2.Template(user_tpl).render()\n"
            "    resp = requests.get(target_url, allow_redirects=True)\n"
            "    return out, resp, sig\n"
        )
        rep_bad = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.audit_ecdsa_ssti_and_ipv6_ssrf_security(vuln_src)
        self.assertFalse(rep_bad.formal_ecdsa_ssti_ipv6_ssrf_safe)
        self.assertFalse(rep_bad.ecdsa_rfc6979_and_ecdh_curve_clean)
        self.assertFalse(rep_bad.ssti_sandboxed_template_clean)
        self.assertFalse(rep_bad.ipv6_mapped_and_encoded_ssrf_clean)
        self.assertGreaterEqual(len(rep_bad.violations), 3)

        clean_src = "def safe_fn(x: int) -> int:\n    return x + 1\n"
        rep_clean = ECDSARFC6979InvalidCurveSSTISandboxAndIPv6MappedSSRFProver.audit_ecdsa_ssti_and_ipv6_ssrf_security(clean_src)
        self.assertTrue(rep_clean.formal_ecdsa_ssti_ipv6_ssrf_safe)


    def test_jwk_header_injection_algorithm_confusion_rsa_oaep_and_sri_prover(self):
        from aleph_core.verification import JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver

        # 1. RFC 8725 JWT Header & Key Confusion Verification
        ok_jwt, _ = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_jwt_rfc8725_header_and_key_binding(
            {"alg": "RS256", "typ": "JWT", "kid": "key_2026_prod"},
            {"RS256"},
            "-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8A...",
            {"key_2026_prod"}
        )
        self.assertTrue(ok_jwt)

        ok_jku, msg_jku = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_jwt_rfc8725_header_and_key_binding(
            {"alg": "RS256", "jku": "https://evil.com/jwks.json"},
            {"RS256"},
            "-----BEGIN PUBLIC KEY-----...",
            None
        )
        self.assertFalse(ok_jku)
        self.assertIn("jku", msg_jku)

        ok_conf, msg_conf = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_jwt_rfc8725_header_and_key_binding(
            {"alg": "HS256", "kid": "key_2026_prod"},
            {"HS256"},
            "-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8A...",
            {"key_2026_prod"}
        )
        self.assertFalse(ok_conf)
        self.assertIn("CVE-2026-0265", msg_conf)

        # 2. Marvin / Bleichenbacher PKCS#1 v1.5 Oracle vs RSA-OAEP SHA-256
        ok_oaep, _ = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_rsa_oaep_and_key_size(
            "RSA-OAEP", "SHA-256", "SHA-256", 3072
        )
        self.assertTrue(ok_oaep)

        ok_pkcs1, msg_pkcs1 = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_rsa_oaep_and_key_size(
            "PKCS1v15", "SHA-256", "SHA-256", 2048
        )
        self.assertFalse(ok_pkcs1)
        self.assertIn("Marvin", msg_pkcs1)

        # 3. Subresource Integrity (SRI) & Cross-Origin Isolation (COOP/COEP/CORP)
        ok_sri, _ = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_sri_and_cross_origin_headers(
            [{"src": "https://cdn.example.com/lib.js", "integrity": "sha384-" + "a" * 64, "crossorigin": "anonymous"}],
            {
                "Cross-Origin-Opener-Policy": "same-origin",
                "Cross-Origin-Embedder-Policy": "require-corp",
                "Cross-Origin-Resource-Policy": "same-origin"
            }
        )
        self.assertTrue(ok_sri)

        ok_no_sri, _ = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_sri_and_cross_origin_headers(
            [{"src": "https://cdn.example.com/lib.js"}],
            {"Cross-Origin-Opener-Policy": "same-origin"}
        )
        self.assertFalse(ok_no_sri)

        # 4. AST Security Audit
        vuln_src = (
            "import jwt\n"
            "from cryptography.hazmat.primitives.asymmetric import padding\n"
            "def bad_auth(token, pub_key_pem, ciphertext, priv_key):\n"
            "    # -----BEGIN PUBLIC KEY-----\n"
            "    claims = jwt.decode(token, pub_key_pem, algorithms=['RS256', 'HS256'])\n"
            "    pt = priv_key.decrypt(ciphertext, padding.PKCS1v15())\n"
            "    html = '<script src=\"https://cdn.evil.com/sdk.js\"></script>'\n"
            "    return claims, pt, html\n"
        )
        rep_bad = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.audit_jwk_rsaoaep_and_sri_security(vuln_src)
        self.assertFalse(rep_bad.formal_jwk_rsaoaep_sri_safe)
        self.assertFalse(rep_bad.jwt_rfc8725_header_and_alg_clean)
        self.assertFalse(rep_bad.rsa_oaep_sha256_anti_marvin_clean)
        self.assertFalse(rep_bad.sri_and_cross_origin_isolation_clean)
        self.assertGreaterEqual(len(rep_bad.violations), 3)

        clean_src = "def safe_fn(x: int) -> int:\n    return x + 1\n"
        rep_clean = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.audit_jwk_rsaoaep_and_sri_security(clean_src)
        self.assertTrue(rep_clean.formal_jwk_rsaoaep_sri_safe)


    def test_webauthn_passkey_origin_binding_nosql_ldap_and_archive_slip_prover(self):
        from aleph_core.verification import WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver
        import hashlib

        # 1. WebAuthn / FIDO2 Passkey Assertion Verification
        rp_id = "auth.aleph.local"
        rp_hash = hashlib.sha256(rp_id.encode("utf-8")).hexdigest()
        client_data = {
            "type": "webauthn.get",
            "origin": "https://auth.aleph.local",
            "challenge": "chal_random_256bit_token"
        }
        ok_wa, _ = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.verify_webauthn_assertion(
            client_data, "webauthn.get", "https://auth.aleph.local", "chal_random_256bit_token",
            rp_hash, rp_id, auth_data_flags=0x05, new_sign_count=12, stored_sign_count=11
        )
        self.assertTrue(ok_wa)

        ok_clone, msg_clone = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.verify_webauthn_assertion(
            client_data, "webauthn.get", "https://auth.aleph.local", "chal_random_256bit_token",
            rp_hash, rp_id, auth_data_flags=0x05, new_sign_count=11, stored_sign_count=11
        )
        self.assertFalse(ok_clone)
        self.assertIn("Cloned", msg_clone)

        # 2. NoSQL Operator Injection & LDAP Filter Escaping
        ok_ns, _, _ = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.verify_nosql_query_and_ldap_filter(
            {"username": "matias", "role": "engineer"}, "matias_cardozo"
        )
        self.assertTrue(ok_ns)

        ok_inj, msg_inj, _ = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.verify_nosql_query_and_ldap_filter(
            {"username": "admin", "password": {"$ne": None}}, "matias"
        )
        self.assertFalse(ok_inj)
        self.assertIn("CWE-943", msg_inj)

        # 3. Zip-Slip / Tar-Slip & Symlink Archive Confinement
        ok_arch, _ = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.verify_archive_extraction_entries(
            "/tmp/safe_extract",
            [{"name": "subdir/readme.txt", "type": "file", "size": 512}]
        )
        self.assertTrue(ok_arch)

        ok_slip, msg_slip = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.verify_archive_extraction_entries(
            "/tmp/safe_extract",
            [{"name": "../../etc/cron.d/pwn", "type": "file", "size": 128}]
        )
        self.assertFalse(ok_slip)
        self.assertIn("CWE-22", msg_slip)

        # 4. AST Security Audit
        vuln_src = (
            "def bad_passkey_and_extract(assertion, tar, db, request):\n"
            "    tar.extractall('/tmp/out')\n"
            "    user = db.users.find_one({'user': request.json['user']})\n"
            "    return user\n"
        )
        rep_bad = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.audit_webauthn_nosql_and_archive_security(vuln_src)
        self.assertFalse(rep_bad.formal_webauthn_nosql_archive_safe)
        self.assertFalse(rep_bad.nosql_and_ldap_filter_taint_clean)
        self.assertFalse(rep_bad.archive_zip_tar_slip_clean)

        clean_src = "def safe_fn(x: int) -> int:\n    return x + 1\n"
        rep_clean = WebAuthnPasskeyOriginBindingNoSQLLDAPAndArchiveSlipProver.audit_webauthn_nosql_and_archive_security(clean_src)
        self.assertTrue(rep_clean.formal_webauthn_nosql_archive_safe)


