        self.assertFalse(rep_bad.argon2id_rfc9106_and_hkdf_clean)
        self.assertFalse(rep_bad.host_header_and_sni_binding_clean)
        self.assertFalse(rep_bad.grpc_protobuf_framing_and_reflection_clean)
        self.assertGreaterEqual(len(rep_bad.violations), 3)

        clean_src = "def safe_fn(x: int) -> int:\n    return x + 1\n"
        rep_clean = Argon2idHKDFKeyDerivationHostHeaderInjectionAndgRPCFramingProver.audit_argon2id_hkdf_host_and_grpc_security(clean_src)
