import hashlib
import hmac

def safe_spake2plus_rfc9383(password: bytes, salt: bytes, shareP: bytes, confirmV: bytes, expected_mac: bytes) -> bool:
    derived = hashlib.pbkdf2_hmac("sha256", password, salt, 600000, dklen=64)
