        self.assertTrue(rep_safe.blind_rsa_rfc9474_and_privacy_pass_rfc9578_clean)
        self.assertTrue(rep_safe.w3c_permissions_policy_and_iframe_allow_clean)
        self.assertTrue(rep_safe.kubelet_10250_10255_and_cri_streaming_ssrf_clean)
        self.assertEqual(len(rep_safe.violations), 0)


