def secure_verify_ocsp_extended_revoked_rfc6960(extended_revoked_ext: bool, revocation_reason: int, revocation_time: str, has_crl_extensions: bool, issuer_name_hash: bytes, expected_name_hash: bytes, issuer_key_hash: bytes, expected_key_hash: bytes) -> bool:
    if not extended_revoked_ext or revocation_reason != 6 or revocation_time != "19700101000000Z" or has_crl_extensions:
        raise ValueError("RFC 6960 extended revoked non-issued certificate validation failed")
    return hmac.compare_digest(issuer_name_hash, expected_name_hash) and hmac.compare_digest(issuer_key_hash, expected_key_hash)

