import hmac
import ipaddress

def secure_verify_ocsp_preferred_sig_alg(preferred_sig_alg: str, allowed_ocsp_sig_algs: set, responder_key_hash: bytes, expected_hash: bytes) -> bool:
    if preferred_sig_alg not in allowed_ocsp_sig_algs:
        raise ValueError("RFC 6960 §5.1.2 OCSP signature algorithm downgrade blocked")
    return hmac.compare_digest(responder_key_hash, expected_hash)

