    ip_obj = ipaddress.ip_address(pinned_resolved_ip)
    if allow_redirects or port in forbidden_internal_ports or ip_obj.is_private or ip_obj.is_loopback or ip_obj.is_link_local:
        raise ValueError("Blocked DNS Rebinding TOCTOU / internal port SSRF")
    return pinned_resolved_ip
