        prover = PrunedLandmarkHubLabelingEpochReclamationAndQuestKVCacheProver()
        rust_unsafe = """
        pub async fn read_lockfree_node(ptr: &Atomic<Node>) -> u64 {
            let guard = crossbeam_epoch::pin();
            let shared = ptr.load(Ordering::Acquire, unsafe { crossbeam_epoch::unprotected() });
            let val = unsafe { shared.deref().value };
            async_flush_metrics().await;
            return val;
        }
        """
