    def test_weak_bisimulation_and_rfc9497_voprf_prover_clean_pass(self):
        from aleph_core.verification import WeakBisimulationAndRFC9497VOPRFProver
        transitions = [
            {"source": "SPEC_0", "action": "request_ast", "target": "SPEC_1"},
            {"source": "SPEC_1", "action": "emit_pcc", "target": "SPEC_0"},
            {"source": "IMPL_0", "action": "tau", "target": "IMPL_CACHE"},
            {"source": "IMPL_CACHE", "action": "request_ast", "target": "IMPL_1"},
            {"source": "IMPL_1", "action": "tau", "target": "IMPL_VERIFY"},
            {"source": "IMPL_VERIFY", "action": "emit_pcc", "target": "IMPL_0"},
        ]
        p = (1 << 255) - 19
        g = 9
        k = 777777777777777
        m = 123456789012345
        voprf = {
            "ciphersuite": "VOPRF(ristretto255, SHA-512)",
            "mode": 1,
            "generator_G": g,
            "server_secret_scalar_k": k,
            "blinded_element_M": m,
            "public_key_Y": (k * g) % p,
            "evaluated_element_Z": (k * m) % p,
            "dleq_nonce_r": 999999999
        }
        rep = WeakBisimulationAndRFC9497VOPRFProver.prove_weak_bisimulation_and_evaluate_rfc9497_voprf(
            lts_transitions=transitions,
            spec_initial_state="SPEC_0",
            impl_initial_state="IMPL_0",
            voprf_params=voprf,
            parent_bundle_sha256="4c2b162366b7e398cc539ace6c22eb415a9b12df2de20ad9c810d41d7df10776",
            release_version="10.4.0"
        )
        self.assertTrue(rep.proven_weak_bisimilar_and_rfc9497_voprf_valid)
        self.assertTrue(rep.initial_states_bisimilar)
        self.assertEqual(rep.rfc9497_voprf_envelope["spec"], "IETF-RFC-9497-VOPRF")
        self.assertEqual(len(rep.bisim_voprf_pcc_seal_sha256), 64)

