    def test_farkas_polyhedral_invariant_and_rfc9530_digest_prover_clean_pass(self):
        import hashlib, base64
        from aleph_core.verification import FarkasLemmaPolyhedralInvariantAndRFC9530DigestProver
        # x + y <= 10, x - y <= 4  ==>  2x <= 14  (lambda = [1.0, 1.0])
        mat_a = [[1.0, 1.0], [1.0, -1.0]]
        vec_b = [10.0, 4.0]
        x0 = [5.0, 3.0]
        target_c = [2.0, 0.0]
        target_d = 15.0
        lambdas = [1.0, 1.0]
        payload = '{"jsonrpc":"2.0","method":"tools/list","id":114}'
        b64 = base64.b64encode(hashlib.sha256(payload.encode("utf-8")).digest()).decode("ascii")
        rfc9530 = {
            "digest_algorithm": "sha-256",
            "representation_payload": payload,
            "claimed_repr_digest_header": f"sha-256=:{b64}:"
        }
        rep = FarkasLemmaPolyhedralInvariantAndRFC9530DigestProver.prove_farkas_polyhedral_invariant_and_verify_rfc9530_digest(
            matrix_A=mat_a,
            vector_b=vec_b,
            feasible_witness_x=x0,
            target_c=target_c,
            target_d=target_d,
            farkas_multipliers_lambda=lambdas,
            rfc9530_params=rfc9530,
            parent_bundle_sha256="2fb7db92fb9a02eab9f148602c40119ada25331a7471ceab1dee9f79b4fb3afc",
            release_version="11.2.0"
        )
        self.assertTrue(rep.proven_farkas_polyhedral_entailment_and_rfc9530_digest_valid)
        self.assertAlmostEqual(rep.farkas_dual_bound, 14.0, places=4)
        self.assertEqual(rep.rfc9530_digest_fields_envelope["spec"], "IETF-RFC-9530-DIGEST-FIELDS")
        self.assertEqual(len(rep.farkas_rfc9530_pcc_seal_sha256), 64)

