    def test_axiomatic_weak_memory_model_acq_rel_and_seq_cst_litmus_prover(self):
        from aleph_core.verification import AxiomaticWeakMemoryModelAcqRelAndSeqCstLitmusProver
        # Case A: Sound Release/Acquire MP pair, SeqCst Store-Buffering barrier, and unbroken RMW release sequence with Acquire CAS failure
        rep_safe = AxiomaticWeakMemoryModelAcqRelAndSeqCstLitmusProver.verify_weak_memory_model_and_litmus(
            message_passing_pairs=[
                {"pattern_id": "MP_RING_PUBLISH", "flag_store_ordering": "Release", "flag_load_ordering": "Acquire", "has_release_acquire_fence_pair": False}
            ],
            store_buffering_barriers=[
                {"barrier_id": "SB_DEQUE_STEAL", "t1_uses_seq_cst_or_full_fence_between_store_and_load": True, "t2_uses_seq_cst_or_full_fence_between_store_and_load": True, "uses_only_release_acquire_for_dekker_or_steal": False}
            ],
            rmw_cas_operations=[
                {"rmw_id": "CAS_TICKET_CLAIM", "release_sequence_broken_by_foreign_plain_store": False, "reads_shared_data_on_cas_failure_branch": True, "cas_failure_ordering": "Acquire"}
            ],
            concurrency_module_id="codere_wmm_safe"
        )
        self.assertTrue(rep_safe.proven_weak_memory_model_and_litmus_sound)
        self.assertTrue(rep_safe.message_passing_release_acquire_hb_verified)
        self.assertTrue(rep_safe.store_buffering_seq_cst_total_order_verified)
        self.assertTrue(rep_safe.rmw_release_sequence_and_cas_failure_order_verified)
        self.assertEqual(len(rep_safe.pcc_certificate_sha256), 64)

        # Case B: Relaxed MP race on ARM64, AcqRel-only Store-Buffering bug, and broken Release Sequence + Relaxed CAS failure read
        rep_bad = AxiomaticWeakMemoryModelAcqRelAndSeqCstLitmusProver.verify_weak_memory_model_and_litmus(
            message_passing_pairs=[
                {"pattern_id": "MP_RELAXED_RACE", "flag_store_ordering": "Relaxed", "flag_load_ordering": "Relaxed", "has_release_acquire_fence_pair": False}
            ],
            store_buffering_barriers=[
                {"barrier_id": "SB_BROKEN_DEKKER", "t1_uses_seq_cst_or_full_fence_between_store_and_load": False, "t2_uses_seq_cst_or_full_fence_between_store_and_load": False, "uses_only_release_acquire_for_dekker_or_steal": True}
            ],
            rmw_cas_operations=[
                {"rmw_id": "CAS_STALE_READ", "release_sequence_broken_by_foreign_plain_store": True, "reads_shared_data_on_cas_failure_branch": True, "cas_failure_ordering": "Relaxed"}
            ],
            concurrency_module_id="codere_wmm_buggy"
        )
        self.assertFalse(rep_bad.proven_weak_memory_model_and_litmus_sound)
        self.assertFalse(rep_bad.message_passing_release_acquire_hb_verified)
        self.assertFalse(rep_bad.store_buffering_seq_cst_total_order_verified)
        self.assertFalse(rep_bad.rmw_release_sequence_and_cas_failure_order_verified)
        self.assertGreaterEqual(len(rep_bad.message_passing_hb_violations), 1)
        self.assertGreaterEqual(len(rep_bad.store_buffering_seq_cst_violations), 1)
        self.assertGreaterEqual(len(rep_bad.rmw_and_cas_ordering_violations), 2)


