        rep_safe = CompilerSSARangeCheckEliminationAndSpeculativeLoadHardeningProver.verify_compiler_ssa_rce_and_slh(
            ssa_ir_rewrites=[
                {"rewrite_id": "GVN_SELECT_01", "def_block_dominates_all_uses_and_phi_preds": True, "converts_conditional_branch_to_eager_select": True, "inserts_freeze_before_eager_select": True, "target_never_more_poison_than_source": True}
            ],
            jit_rce_loops=[
                {"loop_id": "RCE_SAFE_LOOP", "induction_var_upper_limit": 1000, "access_const_offset_k": 16, "array_length": 2048, "type_max_int_bound": 0x7FFFFFFF, "elides_in_loop_bounds_check": True}
            ],
            spectre_v1_guarded_loads=[
                {"load_id": "SLH_KEY_TABLE", "transmits_loaded_val_to_cache_gadget": True, "tracks_cmov_csel_speculative_predicate_mask": True, "applies_slh_mask_to_index_or_pointer": True}
            ],
            compiler_pass_id="codere_compiler_safe"
        )
