        self.assertTrue(rep_safe.alive2_ssa_dominance_and_poison_freeze_verified)
        self.assertTrue(rep_safe.jit_range_check_elimination_no_wraparound_verified)
        self.assertTrue(rep_safe.spectre_v1_speculative_load_hardening_mask_verified)
        self.assertEqual(len(rep_safe.pcc_certificate_sha256), 64)

        # Case B: Broken SSA dominance + unfreezed poison select, 32-bit overflow in RCE (0x7FFFFFF0 + 0x20 > 0x7FFFFFFF), and unmasked Spectre-v1 gadget
        rep_bad = CompilerSSARangeCheckEliminationAndSpeculativeLoadHardeningProver.verify_compiler_ssa_rce_and_slh(
            ssa_ir_rewrites=[
                {"rewrite_id": "INSTCOMBINE_POISON", "def_block_dominates_all_uses_and_phi_preds": False, "converts_conditional_branch_to_eager_select": True, "inserts_freeze_before_eager_select": False, "target_never_more_poison_than_source": False}
            ],
            jit_rce_loops=[
                {"loop_id": "RCE_WRAP_0DAY", "induction_var_upper_limit": 0x7FFFFFF0, "access_const_offset_k": 0x20, "array_length": 4096, "type_max_int_bound": 0x7FFFFFFF, "elides_in_loop_bounds_check": True}
            ],
            spectre_v1_guarded_loads=[
                {"load_id": "SPECTRE_GADGET_01", "transmits_loaded_val_to_cache_gadget": True, "tracks_cmov_csel_speculative_predicate_mask": False, "applies_slh_mask_to_index_or_pointer": False}
            ],
            compiler_pass_id="codere_compiler_buggy"
        )
        self.assertFalse(rep_bad.proven_compiler_ssa_rce_and_slh_sound)
        self.assertFalse(rep_bad.alive2_ssa_dominance_and_poison_freeze_verified)
        self.assertFalse(rep_bad.jit_range_check_elimination_no_wraparound_verified)
        self.assertFalse(rep_bad.spectre_v1_speculative_load_hardening_mask_verified)
        self.assertGreaterEqual(len(rep_bad.alive2_ssa_and_poison_violations), 3)
