        unsafe_sql = """
        ALTER SYSTEM SET io_method = 'sync';
        SET app.current_tenant_id = '0195f3a0-0000-7000-8000-000000000001';
        SELECT set_config('request.jwt.claim.sub', 'user_123', false);
        ALTER TABLE public.orders_v1 RENAME TO orders_v2;
        """
        rep_fail = PG18AsyncIoWorkerUringSubsystemSupavisorTransactionPoolSetLocalIsolationAndZeroDowntimeTableRenameCompatViewProver.verify_sql_ddl(unsafe_sql)
