    def test_pg18_virtual_generated_cols_vault_definer_and_unique_using_index_prover(self):
        """Test #627: Verifies v19.0.0 PG18 VIRTUAL generated columns, Supabase Vault SECURITY DEFINER confinement, and zero-downtime PK/UNIQUE USING INDEX promotion."""
        from aleph_core.verification.z3_prover import (
            PG18VirtualGeneratedColumnWriteAmplificationGuardSupabaseVaultSecurityDefinerSearchPathConfinementAndZeroDowntimeUniquePkUsingIndexProver,
        )
        safe_sql = """
        ALTER TABLE public.ledger_entries ADD COLUMN display_total_cents bigint GENERATED ALWAYS AS (subtotal_cents + tax_cents) VIRTUAL;
        CREATE UNIQUE INDEX CONCURRENTLY idx_ledger_entries_tenant_ext_uq ON public.ledger_entries (tenant_id, external_ref);
        ALTER TABLE public.ledger_entries ADD CONSTRAINT uq_ledger_entries_tenant_ext UNIQUE USING INDEX idx_ledger_entries_tenant_ext_uq;
        CREATE OR REPLACE FUNCTION public.get_tenant_webhook_secret(p_tenant_id uuid)
        RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
        BEGIN
          RETURN (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'tenant_' || p_tenant_id::text);
        END; $$;
        REVOKE ALL ON FUNCTION public.get_tenant_webhook_secret(uuid) FROM PUBLIC, anon;
        """
        rep_ok = PG18VirtualGeneratedColumnWriteAmplificationGuardSupabaseVaultSecurityDefinerSearchPathConfinementAndZeroDowntimeUniquePkUsingIndexProver.verify_sql_ddl(safe_sql)
