        report_bad = PG18BTreeDeduplicationPostingListCompressionSupabaseRlsRealtimePresenceStateQuotaGuardAndZeroDowntimeColumnNotNullCheckValidationProver.verify_pg18_btree_dedup_realtime_presence_rls_and_not_null_validation(
            invalid_spec
        )
        self.assertFalse(report_bad.is_valid)
        self.assertIn("idx_bloated_no_dedup_100_fill", report_bad.misconfigured_btree_dedup_indexes)
        self.assertIn("global_unprotected_presence", report_bad.vulnerable_presence_rls_channels)
