    def test_level_506_omega_continual_self_improvement_and_internal_bitacora_vault_prover(self):
        """Nivel 506 (v33.0.0 — REG-330): Verifica que las 350 reglas de la Bitácora estén dentro de El Aleph con 0.0% olvido."""
        from aleph_core.verification import OmegaContinualSelfImprovementHippoRAG2TitansZeroForgettingAndBitacoraVaultProver
        rep_ok = OmegaContinualSelfImprovementHippoRAG2TitansZeroForgettingAndBitacoraVaultProver.verify_and_synthesize(
            query_context="PostgreSQL 18 zero-downtime DDL, CSS subgrid WCAG 2.2, PageRank KV-Cache y consenso BFT",
            min_required_rules=350,
            simulate_tamper_or_forgetting=False,
        )
        self.assertTrue(rep_ok.proven)
        self.assertEqual(rep_ok.level, 506)
        self.assertGreaterEqual(rep_ok.total_internal_bitacora_rules, 350)
        self.assertEqual(rep_ok.catastrophic_forgetting_rate_pct, 0.0)
        self.assertTrue(rep_ok.merkle_chain_integrity_valid)
        self.assertTrue(rep_ok.hipporag2_ppr_recall_verified)
        self.assertTrue(rep_ok.titans_surprise_momentum_verified)
        self.assertTrue(rep_ok.textgrad_differentiation_verified)
        self.assertTrue(rep_ok.dgm_alphaevolve_pareto_verified)
        self.assertTrue(rep_ok.voyager_skill_ast_verified)

        rep_bad = OmegaContinualSelfImprovementHippoRAG2TitansZeroForgettingAndBitacoraVaultProver.verify_and_synthesize(
            simulate_tamper_or_forgetting=True,
        )
        self.assertFalse(rep_bad.proven)
        self.assertGreater(len(rep_bad.violations), 0)

    def test_level_506_hipporag2_ppr_query_and_experiential_rule_learning_zero_forgetting(self):
        """Verifica que HippoRAG 2 PPR recupere reglas de todos los nodos y que aprender una regla nueva jamás olvide las anteriores."""
        from aleph_core.self_improvement import AlephOmegaContinualSelfImprovementEngine
        omega = AlephOmegaContinualSelfImprovementEngine()
        initial_count = len(omega.rules)
        self.assertGreaterEqual(initial_count, 350)

        # Query for PostgreSQL 18 / Supabase RLS rules
        pg_matches = omega.query_hipporag2_ppr("PostgreSQL 18 UUIDv7 Supabase RLS ATTACH PARTITION", top_k=5)
        self.assertEqual(len(pg_matches), 5)
        self.assertGreater(pg_matches[0]["hybrid_hipporag2_score"], 0.1)

        # Learn a new experiential rule in-memory (persist_to_disk=False for test isolation)
        learn_res = omega.learn_experiential_rule(
            friction_or_error="Desincronización de caché semántico bajo mutación concurrente de subagentes",
            si_clause="SI múltiples subagentes actualizan el grafo asociativo en paralelo",
            entonces_clause="ENTONCES serializar commits mediante cadena Merkle SHA-256 y recalcular Personalized PageRank incremental",
            evitar_clause="EVITAR sobrescrituras destructivas que degraden pesos EWC",
            shard="MASTER-V33",
            persist_to_disk=False,
        )
        self.assertEqual(learn_res["status"], "NEW_RULE_COMMITTED_ZERO_FORGETTING")
        self.assertEqual(len(omega.rules), initial_count + 1)
        chain_ok, _, violations = omega.verify_zero_forgetting_merkle_chain()
        self.assertTrue(chain_ok)
        self.assertEqual(len(violations), 0)

    def test_level_506_mcp_tools_725_to_730_dispatch(self):
        """Verifica el despacho JSON-RPC 2.0 de las 6 nuevas herramientas MCP (#725..#730) del motor Omega v33.0.0."""
        from aleph_core.engine import AlephUniversalMCPServer
        srv = AlephUniversalMCPServer()
        for tool_name, args in [
            ("aleph_prove_omega_continual_self_improvement_hipporag2_titans_zero_forgetting_and_bitacora_vault", {}),
            ("aleph_bitacora_query_hipporag2_ppr", {"query": "CSS subgrid content-visibility WCAG 2.2", "top_k": 4}),
            ("aleph_bitacora_enforce_pre_turn_gate", {"code_or_plan": "SELECT id FROM users WHERE tenant_id = auth.uid();"}),
            ("aleph_bitacora_learn_experiential_rule", {
                "friction_or_error": "Latencia en lectura de reglas",
                "si_clause": "SI se consulta la bitácora en cada turno",
                "entonces_clause": "ENTONCES usar el índice en memoria HippoRAG 2 PPR de El Aleph",
                "evitar_clause": "EVITAR abrir archivos Excel externos en caliente",
                "persist_to_disk": False,
            }),
            ("aleph_omega_dgm_alphaevolve_self_improve", {"task_description": "Optimizar latencia PPR"}),
            ("aleph_bitacora_vault_status_and_telemetry", {}),
        ]:
            resp = srv.handle_jsonrpc_request({
                "jsonrpc": "2.0",
                "id": 99,
                "method": "tools/call",
                "params": {"name": tool_name, "arguments": args},
            })
            self.assertIn("result", resp, f"Fallo en herramienta MCP {tool_name}: {resp}")
            self.assertFalse(resp["result"].get("isError", False))


